/* Original, type-specific demonstration canvases. Reference photographs are not collection assets. */
(() => {
 const A=window.Art;let seq=0;
 const ic={close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',undo:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 0 14"/>',redo:'<path d="m16 4 5 5-5 5m5-5H11a7 7 0 0 0 0 14"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',chevron:'<path d="m9 5 7 7-7 7"/>',rotate:'<path d="M20 9a8 8 0 1 0 0 7M20 3v6h-6"/>',palette:'<circle cx="12" cy="12" r="8"/><path d="M12 4v16M4 12h8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
 const oldIcon=A.icon;A.icon=(n,size=20)=>ic[n]?`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ic[n]}</svg>`:oldIcon(n,size);
 function render(w={},stage=false){const item=window.Studio.getItem(w.itemId);const canvas=stage&&item.category==='enamel'?'plate':w.canvas||window.Studio.category(item.category).canvas;const image=window.LocalStore?.image(w.imageId);if(canvas==='cup')return A.cup({...w,pattern:w.pattern||item.pattern,cup:w.color,source:w.imageId?'own':'museum',image});
 const id='object-'+(++seq),p=A.palette.find(p=>p.id===(w.color||'white'))||A.palette[0],pattern=w.pattern||item.pattern;
 const artwork=w.imageId?(image?`<image href="${image}" x="-70" y="-70" width="140" height="140" preserveAspectRatio="xMidYMid meet"/>`:'<rect x="-50" y="-40" width="100" height="80" fill="none" stroke="#355b68" stroke-dasharray="5 5"/><text text-anchor="middle" y="5" font-size="13" fill="#355b68">图片待恢复</text>'):A.motif(pattern);
 let body='',clip='',center=[180,161],unit=1.12;
 if(canvas==='plate'){clip='<circle cx="180" cy="158" r="111"/>';body=`<ellipse cx="180" cy="295" rx="104" ry="9" fill="#202321" opacity=".08"/><circle cx="180" cy="158" r="135" fill="${p.rim}"/><circle cx="180" cy="158" r="130" fill="url(#${id}-glaze)"/><circle cx="180" cy="158" r="119" fill="none" stroke="#a7b6b0" stroke-width=".7"/><circle cx="180" cy="158" r="113" fill="none" stroke="${p.rim}" stroke-opacity=".3"/><path d="M65 120A121 121 0 0 1 246 58" fill="none" stroke="#fff" stroke-width="3" opacity=".8"/>`;}
 if(canvas==='stamp'){clip='<rect x="88" y="57" width="184" height="196"/>';unit=.98;body=`<rect x="71" y="29" width="218" height="268" fill="${p.color}" stroke="#c6c7bd" stroke-width="1"/><rect x="86" y="45" width="188" height="234" fill="none" stroke="#355b68" stroke-width="1"/><path d="M94 240H266" stroke="#355b68" stroke-width=".6"/><text x="99" y="263" font-size="12" fill="#355b68" letter-spacing="2">物之再生 · 示意</text><text x="100" y="69" font-family="monospace" font-size="10" fill="#355b68">POSTAGE / STUDY</text>${Array.from({length:15},(_,i)=>`<circle cx="71" cy="38" r="4" transform="translate(0 ${i*18})" fill="#eeede7"/><circle cx="289" cy="38" r="4" transform="translate(0 ${i*18})" fill="#eeede7"/>`).join('')}${Array.from({length:12},(_,i)=>`<circle cx="81" cy="29" r="4" transform="translate(${i*18} 0)" fill="#eeede7"/><circle cx="81" cy="297" r="4" transform="translate(${i*18} 0)" fill="#eeede7"/>`).join('')}`;}
 if(canvas==='wrapper'){clip='<rect x="86" y="75" width="188" height="170"/>';unit=.85;body=`<path d="M20 91 86 72H274L340 91 329 111 340 134 329 157 340 181 329 203 340 226 274 246H86L20 226 31 203 20 181 31 157 20 134 31 111Z" fill="${p.color}" stroke="#b9afa0"/><path d="M86 73V245M274 73V245" stroke="#b77c62" stroke-width="2"/><path d="M40 107 76 94M40 137 76 129M40 203 76 218M284 94 320 107M284 129 320 137M284 218 320 203" stroke="#c9c5b9"/><rect x="98" y="86" width="164" height="146" fill="none" stroke="#b77c62" stroke-width=".7"/><text x="180" y="220" font-size="11" text-anchor="middle" fill="#8f4d3d" letter-spacing="6">一纸甜意</text>`;center=[180,153];}
 if(canvas==='part'){clip='<circle cx="180" cy="160" r="67"/>';unit=.68;const gear=Array.from({length:64},(_,i)=>{const a=i*Math.PI/32,r=i%4===0||i%4===3?124:141;return (i?'L':'M')+(180+Math.cos(a)*r).toFixed(2)+' '+(160+Math.sin(a)*r).toFixed(2);}).join('')+'Z';body=`<path d="${gear}" fill="#abb0a6" stroke="#626c64" stroke-width="2"/><circle cx="180" cy="160" r="108" fill="none" stroke="#e5e8df" stroke-width="2"/><circle cx="180" cy="160" r="85" fill="#7b867e"/><circle cx="180" cy="160" r="72" fill="${p.color}" stroke="#4d5a54" stroke-width="2"/>${[0,90,180,270].map(a=>`<circle cx="180" cy="64" r="5" fill="#535f56" transform="rotate(${a} 180 160)"/>`).join('')}`;}
 return `<svg viewBox="0 0 360 320" role="img" aria-label="${window.Studio.category(item.category).name}数字设计示意"><defs><radialGradient id="${id}-glaze" cx=".4" cy=".3" r=".8"><stop stop-color="#fffefa"/><stop offset=".7" stop-color="${p.color}"/><stop offset="1" stop-color="#d7dfd6"/></radialGradient><clipPath id="${id}-clip">${clip}</clipPath></defs>${body}<g clip-path="url(#${id}-clip)"><g transform="translate(${center[0]+(Number(w.x)||0)} ${center[1]+(Number(w.y)||0)}) rotate(${Number(w.rotation)||0}) scale(${unit*(Number(w.scale)||100)/100})">${artwork}</g></g></svg>`;
 }
 A.object=render;
})();
